+func serializeValue(value any) any {
+	if value == nil {
+		return nil
+	}
+	switch v := value.(type) {
+	case string, bool:
+		return v
+	case int:
+		return v
+	case int8:
+		return int(v)
+	case int16:
+		return int(v)
+	case int32:
+		return int(v)
+	case int64:
+		return v
+	case float32:
+		return float64(v)
+	case float64:
+		return v
+	case time.Time:
+		epochSec := float64(v.Unix()) + float64(v.Nanosecond())/1e9
+		return map[string]any{
+			"__type": "datetime",
+			"__var":  epochSec,
+		}
+	case time.Duration:
+		return map[string]any{
+			"__type": "timedelta",
+			"__var":  v.Seconds(),
+		}
+	case map[string]any:
+		serialized := make(map[string]any, len(v))
+		for k, val := range v {
+			serialized[k] = serializeValue(val)
+		}
+		return map[string]any{
+			"__type": "dict",
+			"__var":  serialized,
+		}
+	case []string:
+		result := make([]any, len(v))
+		for i, item := range v {
+			result[i] = serializeValue(item)
+		}
+		return result
+	case []any:
+		result := make([]any, len(v))
+		for i, item := range v {
+			result[i] = serializeValue(item)
+		}
+		return result
+	default:
+		rv := reflect.ValueOf(v)
+		switch rv.Kind() {
+		case reflect.Map:
+			serialized := make(map[string]any, rv.Len())
+			for _, key := range rv.MapKeys() {
+				serialized[fmt.Sprint(key.Interface())] = serializeValue(rv.MapIndex(key).Interface())
+			}
+			return map[string]any{
+				"__type": "dict",
+				"__var":  serialized,
+			}
+		case reflect.Slice, reflect.Array:
+			result := make([]any, rv.Len())
+			for i := range result {
+				result[i] = serializeValue(rv.Index(i).Interface())
+			}
+			return result
+		default:
+			return v
