+// unwrapTypeEncoding strips type/var metadata.
+func unwrapTypeEncoding(value any) any {
+	m, ok := value.(map[string]any)
+	if !ok {
+		return value
+	}
+	if _, hasType := m["__type"]; !hasType {
+		return value
+	}
+	if v, hasVar := m["__var"]; hasVar {
+		return v
+	}
+	return value
+}
